const $=s=>document.querySelector(s), esc=v=>String(v??'').replace(/Nhà máy A/g,'Prime Tiền Phong').replace(/Nhà máy B/g,'Prime Đại Việt').replace(/ \(hư cấu\)| \(mô phỏng\)/g,'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
