if(key==='order-remove'){const lines=document.querySelectorAll('.order-line');const row=document.querySelector(`.order-line[data-line-id="${id}"]`);if(lines.length>1)row?.remove();updateOrderTotal();return}
if(key==='lot'){const l=lots.find(x=>x.id===id);open('Chi tiết '+l.lot,`${productCell(l.product)}<div class="summary-box" style="margin-top:24px">${esc(l.plant)} · ${esc(l.location)}<br>Sắc độ: ${esc(l.shade)} · ${esc(l.grade)}<br>Ngày sản xuất: ${l.produced}<br>Chủ hàng: Prime<br>Tồn ghi nhận: ${n(l.qty)} m²<br>${badge(l.quality)}</div><p style="margin-top:18px;font-size:12px">${l.quality==='Đạt chất lượng'?'Có thể xem xét phân bổ theo SKU, lô và sắc độ.':'Lô này bị loại khỏi tồn khả dụng.'}</p>`);return}
if(key==='movement'){open('Phiếu điều chuyển',`<p class="hint">Phiếu điều chuyển là bản demo, chưa thay đổi tồn kho.</p><form id="simple-form" data-message="Phiếu điều chuyển là bản demo, chưa thay đổi tồn kho."><div class="fields"><label>Mã gạch<select>${products.map(pr=>`<option>${pr.id}</option>`).join('')}</select></label><label>Số lượng m²<input type="number" min="1" required></label><label>Từ vị trí<select><option>${context().plant==='all'?'Prime Tiền Phong':context().plant} · K1-A01</option></select></label><label>Đến vị trí<select><option>${context().plant==='all'?'Prime Tiền Phong':context().plant} · K2-B01</option></select></label></div><div class="form-actions"><button class="primary">Lưu phiếu</button></div></form>`);return}
if(key==='reconcile'){const r=db.receipts.find(x=>x.id===id);open('Đối chiếu '+r.ref,`<form id="reconcile-form" data-id="${id}"><div class="summary-box">Tiền vào: ${money(r.amount)} · ${r.date}<br></div><label style="margin-top:20px">Khách hàng<select name="customer">${customers.map(cu=>`<option value="${cu.id}" ${cu.id===r.customer?'selected':''}>${cu.name}</option>`).join('')}</select></label><div class="form-actions"><button class="primary">Xác minh</button></div></form>`);return}
if(key==='allocation'){open('Phân bổ khoản thu',`<div class="summary-box">Khoản thu 120.000.000 ₫<br>Đối trừ HD-MAU-001: 70.000.000 ₫<br>Chưa phân bổ: 50.000.000 ₫</div><p style="font-size:12px;margin-top:18px">Đối trừ theo FIFO và phân bổ nhiều hóa đơn.</p>`);return}
if(key==='receipt'){open('Nhập giao dịch',`<form id="receipt-form"><label>Tham chiếu<input name="ref" placeholder="REF-DEMO-004" maxlength="60" required></label><label style="margin-top:18px">Số tiền<input name="amount" type="number" min="1" required></label><div class="form-actions"><button class="primary">Nhập giao dịch</button></div></form>`);return}
if(key==='plan'){const pl=db.plans.find(x=>x.id===id);open(pl.id,`<p>${p(pl.product).name} · ${normalizePlant(pl.plant)}</p><div class="summary-box" style="margin:20px 0">Tháng 11: ${n(pl.months[0])} m²<br>Tháng 12: ${n(pl.months[1])} m²<br>Tháng 01: ${n(pl.months[2])} m²<br>Năng lực: trong ngưỡng cho phép<br>Nguyên liệu: cần xác nhận men trước khi cam kết.</div>${badge(pl.status)}<div class="form-actions">${btn('Duyệt kế hoạch','plan-approve:'+id,true)}</div>`);return}
if(key==='plan-approve'){const pl=db.plans.find(x=>x.id===id);if(!pl||pl.status==='Đã duyệt')return toast('Phương án đã được duyệt.');if(!saveChange(()=>{pl.status='Đã duyệt';}))return;close();render();toast('Đã duyệt phương án.');return}
if(key==='plan-new'){open('Phương án kế hoạch mới',`<form id="plan-form"><div class="fields"><label class="full">SKU<select name="product">${products.map(pr=>`<option value="${pr.id}">${pr.name}</option>`).join('')}</select></label><label>Tháng bắt đầu<input type="month" value="2026-11" readonly></label><label>Nhà máy<select name="plant">${(context().plant==='all'?PLANTS:[context().plant]).map(pl=>`<option>${pl}</option>`).join('')}</select></label>${[11,12,1].map((m,i)=>`<label>Tháng ${m} · m²<input name="m${i}" type="number" min="0" required></label>`).join('')}</div><div class="form-actions"><button class="primary">Lưu phương án</button></div></form>`);return}
if(key==='pi'){const x=db.exports.find(x=>x.id===id);open(x.id,`<p>${esc(x.customer)} · ${x.country}</p><div class="status-track">${['Xác nhận PI','Sản xuất','Sẵn sàng','Booking','Shipped','Delivered'].map((t,i)=>`<div class="${i<=(id==='PI-2026-001'?1:id==='PI-2026-002'?3:5)?'done':''}">${t}</div>`).join('')}</div><div class="summary-box">${p(x.product).name} · ${n(x.qty)} m²<br>Phiên bản PI: ${x.version}<br>Điều kiện: FOB · ${x.term}<br>ETD: ${x.etd}<br>${badge(x.status)}</div><p style="margin-top:18px;font-size:12px">Thay đổi PI cần phiên bản mới và rà soát lại chứng từ liên quan.</p>`);return}
if(key==='pi-new'){open('Tạo PI',`<form id="simple-form" data-message="Đã lưu PI."><div class="fields"><label>Khách xuất khẩu<input value="Lotus Trading" required></label><label>Thanh toán<select><option>TT100%</option><option>TT đặt cọc 30%</option><option>LC trả ngay</option></select></label><label>Sản phẩm<select>${products.map(pr=>`<option>${pr.name}</option>`).join('')}</select></label><label>Số lượng m²<input type="number" min="1" required></label><label>ETD<input type="date" required></label><label>Incoterm<select><option>FOB</option><option>CIF</option></select></label></div><div class="form-actions"><button class="primary">Lưu PI</button></div></form>`);return}
if(key==='shipment'){open('Shipment Master · SHP-2026-002',`<div class="summary-box">PI-2026-002 · Phiên bản 1<br>4.320 m² Urban Grey<br>12.000 viên · 2.000 hộp · 5 container 20 feet<br>Trọng lượng hàng: 108.000 kg<br>Trọng lượng vỏ: 11.000 kg<br>VGM tổng: 119.000 kg<br>Seal: SEAL-002 (mã giả định)<br>Hải Phòng → Cảng đích Malaysia</div>`);return}
if(key==='doc'){const d=db.documents.find(x=>x.id===id);open(d.type+' · '+d.id,`<div class="summary-box">Shipment: ${d.shipment}<br>PI-2026-002 · ${p(products[1].id).name}<br>4.320 m² · 12.000 viên · 2.000 hộp<br>Phiên bản: V${d.version}<br>Người phụ trách: Logistics<br>${badge(d.status)}</div><div class="hint" style="margin-top:20px">${d.type==='B/L nháp'?'Cần kiểm tra tên người nhận và trọng lượng trước khi duyệt.':'Nguồn: Shipment Master.'}</div><div class="form-actions">${btn('Xuất dữ liệu','doc-export:'+id)}${d.status!=='Đã duyệt'&&d.type!=='B/L nháp'?btn('Duyệt chứng từ','doc-approve:'+id,true):''}</div>`);return}
if(key==='doc-export'){download(id+'.json',JSON.stringify({sample:true,...db.documents.find(x=>x.id===id)},null,2));toast('Đã tải dữ liệu chứng từ.');return}
if(key==='doc-approve'){const d=db.documents.find(x=>x.id===id);if(!saveChange(()=>{d.status='Đã duyệt';}))return;close();render();toast('Đã duyệt chứng từ.');return}
if(key==='checkin'){const v=db.visits.find(x=>x.id===id);if(!saveChange(()=>{v.status='Đã check-in';}))return;render();toast('Đã check-in.');return}
if(key==='visit-new'){open('Lên lịch chuyến thăm',`<form id="visit-form"><div class="fields"><label class="full">Điểm bán<select name="customer">${customers.map(cu=>`<option value="${cu.id}">${cu.name}</option>`).join('')}</select></label><label>Ngày thăm<input name="date" type="date" value="2026-11-02" required></label><label>Mục tiêu<input name="note" placeholder="Giới thiệu mẫu mới"></label></div><div class="form-actions"><button class="primary">Lưu lịch</button></div></form>`);return}
if(key==='draft'){surveyDraft=readSurvey();try{localStorage.setItem('prime-survey-draft',JSON.stringify(surveyDraft));toast('Đã lưu nháp. Ảnh cần chọn lại khi mở nháp.')}catch{toast('Không lưu được nháp trên thiết bị.')}return}
if(key==='survey-detail'){const s=db.surveys.find(x=>x.id===id);open(s.id,`${productCell(s.product)}<div class="summary-box" style="margin:20px 0">${c(s.customer)?.name}<br>${s.date} · ${s.sales}<br>Mức quan tâm: ${s.interest}<br>Tồn Prime: ${s.companyStock==null?'Chưa ghi nhận':n(s.companyStock)+' m²'}<br>Tồn đối thủ: ${s.competitorStock==null?'Chưa ghi nhận':n(s.competitorStock)+' m²'}</div><p>${freeTextHTML(s.note)}</p>`);return}
if(key==='sellout-new'){open('Ghi nhận số bán ra',`<form id="sellout-form"><div class="fields"><label class="full">Khách hàng<select name="customer">${customers.map(cu=>`<option value="${cu.id}">${cu.name}</option>`).join('')}</select></label><label class="full">Sản phẩm<select name="product">${products.map(pr=>`<option value="${pr.id}">${pr.name}</option>`).join('')}</select></label><label>Kỳ báo cáo<input name="period" type="month" value="2026-10" required></label><label>Sell-out m²<input name="qty" type="number" min="0" step=".01" required></label></div><div class="form-actions"><button class="primary">Lưu số bán ra</button></div></form>`);return}
