function moduleFilterControls(){
 if(['survey','roles','activity','export','documents'].includes(page))return '';
 const ctx=viewContext(),rows=kind=>kind==='products'?allProducts.filter(pr=>ctx.plant==='all'||productPlant(pr.id)===ctx.plant):kind==='customers'?allCustomers.filter(cu=>ctx.plant==='all'||customerPlant(cu.id)===ctx.plant):kind==='lots'?scopedRows(allLots,'lots',ctx):kind==='reviews'?fullDb.reviews:scopedRows(fullDb[kind]||[],kind,ctx);
 const spec={
 'web/overview':{kind:'orders',fields:['customer','status','dates']},
 'web/stock':{kind:'lots',fields:['product','location','size','quality','dates']},
 'web/orders':{kind:'orders',fields:['customer','status','dates']},
 'web/ar':{kind:'receipts',fields:['customer','status','dates']},
 'web/market':{kind:'sellouts',fields:['customer','ownership','period']},
 'web/plans':{kind:'plans',fields:['product','status','period']},
 'web/export':{kind:'exports',fields:['country','term','status','dates']},
 'web/documents':{kind:'documents',fields:['type','status','shipment']},
 'customer/home':{kind:'orders',fields:['status','dates']},
 'customer/catalog':{kind:'products',fields:['group','size','surface']},
 'customer/orders':{kind:'orders',fields:['status','dates']},
 'customer/account':{kind:'receipts',fields:['dates']},
 'sales/home':{kind:'visits',fields:['customer','dates']},
 'sales/visits':{kind:'visits',fields:['customer','status','dates']},
 'sales/sellout':{kind:'sellouts',fields:['customer','ownership','period']},
 'sales/customers':{kind:'customers',fields:['region','channel']}
 }[app+'/'+page];
 if(!spec)return '';
 const rs=rows(spec.kind),titles={customer:'Khách hàng',product:'Mã gạch',status:'Trạng thái',quality:'Chất lượng',location:'Location',size:'Kích thước',surface:'Bề mặt',group:'Nhóm gạch',ownership:'Phân loại',country:'Thị trường',term:'Thanh toán',type:'Loại chứng từ',shipment:'Shipment',channel:'Kênh phân phối',region:'Miền'};
 const values=key=>{
 if(key==='customer')return [...new Set(rs.map(r=>r.customer).filter(Boolean))].map(id=>[id,c(id)?.name||id]);
 if(key==='product')return [...new Set(rs.map(r=>r.product).filter(Boolean))].map(id=>[id,p(id)?.name||id]);
 if(key==='ownership')return [['Prime','Prime'],['Đối thủ','Đối thủ']];
 if(['size','surface','group'].includes(key))return [...new Set((spec.kind==='products'?rs:rs.map(r=>p(r.product))).filter(Boolean).map(pr=>pr[key]).filter(Boolean))].map(v=>[v,v]);
 return [...new Set(rs.map(r=>r[key]).filter(Boolean))].map(v=>[v,v]);
 };
 return `<section class="module-filter-panel" aria-label="Tìm kiếm và bộ lọc"><label class="module-search">Tìm kiếm<input id="search" type="search" value="${esc(search)}" placeholder="Tìm mã, tên, khách hàng…" aria-label="Tìm trong module"></label>${spec.fields.map(key=>key==='dates'?`<label>Từ ngày<input type="date" data-module-filter="from" value="${esc(moduleFilters.from||'')}"></label><label>Đến ngày<input type="date" data-module-filter="to" min="${esc(moduleFilters.from||'')}" value="${esc(moduleFilters.to||'')}"></label>`:key==='period'?`<label>Kỳ báo cáo<input type="month" data-module-filter="period" value="${esc(moduleFilters.period||'')}"></label>`:`<label>${titles[key]}<select data-module-filter="${key}"><option value="all">Tất cả</option>${values(key).map(([v,t])=>`<option value="${esc(v)}" ${moduleFilters[key]===v?'selected':''}>${esc(t)}</option>`).join('')}</select></label>`).join('')}<button data-action="clear-module-filters">Xóa bộ lọc</button></section>`;
}

